    /**
     * Tests creating a new FXQuote.
     *
     * @return    FXQuote
     */
    public FXQuote testCreate() throws Throwable {
    FXQuote entity = null;

    LOGGER.info( "FXQuoteTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a FXQuote");

    StringBuilder msg = new StringBuilder( "-- Failed to create a FXQuote" );

    try {
        entity = service.createFXQuote( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getFXQuoteId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a FXQuote with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

