    /**
     * Tests getting all FXQuotes.
     *
     * @return    Collection
     */
    public List<FXQuote> testGetAll() throws Throwable {
    LOGGER.info( "FXQuoteTest:testGetAll() - Retrieving Collection of FXQuotes:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all FXQuote : " );
    List<FXQuote> collection  = null;

    try {
        // call the static get method on the FXQuoteService
        collection = service.getAllFXQuote();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            FXQuote currEntity  = null;
            Iterator<FXQuote> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getFXQuoteId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

